-- Arbeitsrecht Berufsbildung > Berufsbildungsgesetz (BBiG) > Regelungen zur Ausbildungszeit
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss die Ausbildungszeit eines Fachinformatikers im Ausbildungsvertrag festgelegt werden?', 2, '[{"text": "Ja", "correct": true, "because": "§ 8 BBiG verlangt die Vereinbarung der Dauer"}, {"text": "Nein", "correct": false, "because": "Dauer ist vertraglich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Ausbildungszeit eines Fachinformatikers verlängert werden?', 2, '[{"text": "Ja", "correct": true, "because": "§ 8 Abs. 2 BBiG erlaubt Verlängerung bei Nichtbestehen der Prüfung"}, {"text": "Nein", "correct": false, "because": "Verlängerung ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf die Ausbildungszeit eines Fachinformatikers ohne Zustimmung des Betriebs verkürzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "§ 8 Abs. 1 BBiG erfordert Zustimmung beider Parteien"}, {"text": "Ja", "correct": false, "because": "Verkürzung bedarf Einvernehmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Probezeit für die Ausbildung eines Fachinformatikers vorgeschrieben?', 2, '[{"text": "Ja", "correct": true, "because": "§ 7 BBiG schreibt eine Probezeit vor"}, {"text": "Nein", "correct": false, "because": "Probezeit ist verpflichtend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Ausbildungszeit eines Fachinformatikers weniger als zwei Jahre betragen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 8 Abs. 1 BBiG legt eine Mindestdauer von zwei Jahren fest"}, {"text": "Ja", "correct": false, "because": "Mindestdauer ist vorgeschrieben"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage regelt die Dauer der Ausbildungszeit eines Fachinformatikers?', 2, '[{"text": "§ 8 BBiG", "correct": true, "because": "Regelt die Ausbildungszeit"}, {"text": "§ 11 BBiG", "correct": false, "because": "Bezieht sich auf den Ausbildungsplan"}, {"text": "§ 15 BBiG", "correct": false, "because": "Regelt die Berufsschule"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie lange beträgt die übliche Ausbildungszeit für einen Fachinformatiker?', 3, '[{"text": "3 Jahre", "correct": true, "because": "Standarddauer für Fachinformatiker gemäß Ausbildungsordnung"}, {"text": "2 Jahre", "correct": false, "because": "Mindestdauer, aber nicht üblich"}, {"text": "4 Jahre", "correct": false, "because": "Nicht Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Mindestdauer der Probezeit für einen Fachinformatiker gemäß BBiG?', 2, '[{"text": "1 Monat", "correct": true, "because": "§ 7 BBiG legt mindestens 1 Monat fest"}, {"text": "2 Wochen", "correct": false, "because": "Zu kurz"}, {"text": "3 Monate", "correct": false, "because": "Maximal 4 Monate erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer kann die Ausbildungszeit eines Fachinformatikers verkürzen?', 3, '[{"text": "Betrieb und Auszubildender gemeinsam", "correct": true, "because": "§ 8 Abs. 1 BBiG verlangt Einvernehmen"}, {"text": "Nur der Betrieb", "correct": false, "because": "Einvernehmen erforderlich"}, {"text": "Die IHK allein", "correct": false, "because": "IHK genehmigt nur"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Fachinformatiker die Abschlussprüfung nicht besteht?', 3, '[{"text": "Die Ausbildungszeit kann verlängert werden", "correct": true, "because": "§ 8 Abs. 2 BBiG erlaubt dies"}, {"text": "Die Ausbildung endet automatisch", "correct": false, "because": "Verlängerung möglich"}, {"text": "Er muss sofort kündigen", "correct": false, "because": "Nicht vorgeschrieben"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Regelungen zur Ausbildungszeit eines Fachinformatikers sind im BBiG enthalten?', 4, '[{"text": "Mindestdauer von 2 Jahren", "correct": true, "because": "§ 8 Abs. 1 BBiG legt dies fest"}, {"text": "Probezeit von 1 bis 4 Monaten", "correct": true, "because": "§ 7 BBiG regelt die Probezeit"}, {"text": "Feste Dauer von 5 Jahren", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Möglichkeit der Verkürzung", "correct": true, "because": "§ 8 Abs. 1 BBiG erlaubt dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedingungen erlauben eine Verkürzung der Ausbildungszeit eines Fachinformatikers?', 3, '[{"text": "Einvernehmen von Betrieb und Auszubildendem", "correct": true, "because": "§ 8 Abs. 1 BBiG verlangt Zustimmung"}, {"text": "Besondere Leistungen", "correct": true, "because": "Kann Verkürzung begründen"}, {"text": "Wunsch des Auszubildenden allein", "correct": false, "because": "Einvernehmen erforderlich"}, {"text": "Genehmigung durch die IHK", "correct": true, "because": "IHK muss zustimmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gilt für die Probezeit eines Fachinformatikers gemäß BBiG?', 4, '[{"text": "Mindestens 1 Monat", "correct": true, "because": "§ 7 BBiG legt dies fest"}, {"text": "Maximal 4 Monate", "correct": true, "because": "§ 7 BBiG begrenzt die Dauer"}, {"text": "Keine Kündigung möglich", "correct": false, "because": "Kündigung erlaubt"}, {"text": "Verlängerung bei Bedarf", "correct": false, "because": "Nicht vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen hat eine Unterbrechung der Ausbildungszeit eines Fachinformatikers?', 3, '[{"text": "Mögliche Verlängerung der Ausbildung", "correct": true, "because": "§ 8 Abs. 2 BBiG kann dies ermöglichen"}, {"text": "Anrechnung der Unterbrechung", "correct": true, "because": "Abhängig von Dauer und Grund"}, {"text": "Automatisches Ende der Ausbildung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Verkürzung der Ausbildung", "correct": false, "because": "Nicht logisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Ausbildungszeit eines Fachinformatikers?', 3, '[{"text": "Ausbildungsvertrag", "correct": true, "because": "Legt Dauer fest"}, {"text": "Leistungen des Auszubildenden", "correct": true, "because": "Kann Verkürzung ermöglichen"}, {"text": "Persönliche Wünsche", "correct": false, "because": "Nicht allein entscheidend"}, {"text": "Genehmigung durch die IHK", "correct": true, "because": "Bei Änderungen erforderlich"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Ausbildungszeit eines Fachinformatikers beträgt üblicherweise 3 Jahre. b) Eine Verkürzung ist ohne Zustimmung des Betriebs möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "3 Jahre üblich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Probezeit eines Fachinformatikers darf maximal 4 Monate betragen. b) Die Ausbildungszeit kann verlängert werden.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "§ 7 und § 8 BBiG bestätigen dies"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Ausbildungszeit eines Fachinformatikers muss mindestens 2 Jahre betragen. b) Die Probezeit beträgt immer 3 Monate.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mindestdauer 2 Jahre, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine Verkürzung der Ausbildungszeit erfordert Einvernehmen. b) Die Ausbildungszeit endet automatisch nach 2 Jahren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Einvernehmen nötig, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Ausbildungszeit eines Fachinformatikers kann bei Nichtbestehen verlängert werden. b) Die Probezeit ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verlängerung möglich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

